    classes = {r["id"]: r for r in db.execute(sa.select(t["administrative_class"])).mappings()}
    colleges = {r["id"]: r for r in db.execute(sa.select(t["college"])).mappings()}
    students = {r["id"]: r for r in db.execute(sa.select(t["student"])).mappings()}
    counts = {
        "current_baselines": 0,
        "teacher_bindings": 0,
        "manager_appointments": 0,
        "confirmed_class_audiences": 0,
    }
    for student in students.values():
        ac = classes.get(student["administrative_class_id"])
        cid = ac["college_id"] if ac else None
        status = (
            "ENROLLED"
            if student["status"] == "ACTIVE"
            else "GRADUATED"
            if student["status"] == "GRADUATED"
            else "WITHDRAWN"
            if student["status"] == "ARCHIVED"
            else "SUSPENDED"
        )
        snapshot = {
            "class_id": str(ac["id"]) if ac else None,
            "class_code": ac["class_code"] if ac else None,
            "class_name": ac["class_name"] if ac else None,
            "college_id": str(cid) if cid else None,
            "college_name": colleges[cid]["name"]
            if cid in colleges
            else ac["college"]
            if ac
            else None,
            "major_name": ac["major_name"] if ac else None,
            "grade_year": ac["grade_year"] if ac else None,
            "origin": "MIGRATION_CURRENT_ONLY",
        }
        db.execute(
            t["student_enrollment"]
            .insert()
            .values(
                student_id=student["id"],
                administrative_class_id=ac["id"] if ac else None,
                college_id=cid,
                effective_from=today,
                status=status,
                revision=0,
                historical_confirmed=False,
                superseded=False,
                snapshot=snapshot,
                **stamp,
            )
        )
        counts["current_baselines"] += 1
    for qual in db.execute(sa.select(t["volunteer_qualification"])).mappings():
        student = students.get(qual["student_id"])
        ac = classes.get(student["administrative_class_id"]) if student else None
        if ac and ac["college_id"]:
            db.execute(
                t["volunteer_qualification"]
                .update()
                .where(t["volunteer_qualification"].c.id == qual["id"])
                .values(college_id=ac["college_id"])
            )
    role_ids = {r["code"]: r["id"] for r in db.execute(sa.select(t["role"])).mappings()}
    roles = {}
    for row in db.execute(sa.select(t["user_role"])):
        roles.setdefault(row.user_id, set()).add(row.role_id)
    permission_codes = {
        r["id"]: r["code"] for r in db.execute(sa.select(t["permission"])).mappings()
    }
    manager_actions = sorted(
        {
            permission_codes[r.permission_id]
            for r in db.execute(
                sa.select(t["role_permission"]).where(
                    t["role_permission"].c.role_id == role_ids.get("STUDENT_AFFAIRS_MANAGER", -1)
                )
            )
            if permission_codes[r.permission_id]
            not in {"objection.initial_review", "statistics.read"}
        }
    )
    for user in db.execute(sa.select(t["user_account"])).mappings():
        codes = roles.get(user["id"], set())
        if user["status"] != "ACTIVE" or role_ids.get("SUPER_ADMIN") in codes:
            continue
        if role_ids.get("TEACHER_ADMIN") in codes:
            grants = list(
                db.execute(
                    sa.select(t["scoped_grant"]).where(
                        t["scoped_grant"].c.user_id == user["id"],
                        t["scoped_grant"].c.status == "ACTIVE",
                        sa.or_(
                            t["scoped_grant"].c.starts_at.is_(None),
                            t["scoped_grant"].c.starts_at <= now,
                        ),
                        sa.or_(
                            t["scoped_grant"].c.expires_at.is_(None),
                            t["scoped_grant"].c.expires_at > now,
                        ),
                    )
                ).mappings()
            )
            cids = {
                g["college_id"]
                for g in grants
                if g["college_id"] in colleges and colleges[g["college_id"]]["status"] == "ACTIVE"
            }
            if len(cids) == 1:
                db.execute(
                    t["teacher_college_binding"]
                    .insert()
                    .values(user_id=user["id"], college_id=cids.pop(), lock_version=0, **stamp)
                )
                counts["teacher_bindings"] += 1
        elif role_ids.get("STUDENT_AFFAIRS_MANAGER") in codes:
            student = students.get(user["student_id"])
            ac = classes.get(student["administrative_class_id"]) if student else None
            if (
                student
                and student["status"] == "ACTIVE"
                and ac
                and ac["college_id"] in colleges
                and colleges[ac["college_id"]]["status"] == "ACTIVE"
            ):
                db.execute(
                    t["student_manager_appointment"]
                    .insert()
                    .values(
                        user_id=user["id"],
                        college_id=ac["college_id"],
                        effective_from=today,
                        allowed_actions=manager_actions,
                        **stamp,
                    )
                )
                counts["manager_appointments"] += 1
    # 从已确认网格导入的稳定班级 ID、学期和精确课程键恢复班级课源，绝不依据成员并集猜测。
    pairs = set()
    courses = list(db.execute(sa.select(t["course"])).mappings())
    teaching = list(db.execute(sa.select(t["teaching_class"])).mappings())
    for batch in db.execute(
        sa.select(t["import_batch"]).where(
            t["import_batch"].c.target == "grid_timetable",
            t["import_batch"].c.status == "CONFIRMED",
        )
    ).mappings():
        payload, summary = batch["payload_json"] or {}, batch["summary_json"] or {}
        try:
            ac = classes.get(int(summary.get("resource_id", "0")))
        except (ValueError, TypeError):
            continue
        if not ac or payload.get("class_name") not in {ac["class_code"], ac["class_name"]}:
            continue
        for item in payload.get("courses", []):
            matches = [c for c in courses if c["course_name"] == item.get("course_name")]
            if len(matches) != 1:
                continue
            course = matches[0]
            rows = [
                tc
                for tc in teaching
                if tc["semester_id"] == batch["semester_id"]
                and tc["course_id"] == course["id"]
                and tc["class_code"] == f"{ac['class_code']}_{course['course_code']}"
                and tc["college_id"] == ac["college_id"]
            ]
            if len(rows) == 1:
                pairs.add((rows[0]["id"], ac["id"]))
    for tcid, acid in sorted(pairs):
        db.execute(
            t["teaching_class_audience"]
            .insert()
            .values(teaching_class_id=tcid, administrative_class_id=acid)
        )
    counts["confirmed_class_audiences"] = len(pairs)
    # 单一原始课表引用可直接证实；旧合并任务的来源不可逆，保留未知供老师核对。
    schedule = {r["id"]: r for r in db.execute(sa.select(t["course_schedule"])).mappings()}
    for task in db.execute(sa.select(t["inspection_task"])).mappings():
        source = schedule.get(task["course_schedule_id"])
        if (
            source
            and "|grp" not in task["task_key"]
            and source["teaching_class_id"] == task["teaching_class_id"]
        ):
            db.execute(
                t["task_schedule_source"]
                .insert()
                .values(
                    task_id=task["id"],
                    course_schedule_id=source["id"],
                    teaching_class_id=source["teaching_class_id"],
                )
            )
    perm = t["permission"]
    if not db.scalar(sa.select(perm.c.id).where(perm.c.code == "administrator_account.manage")):
        db.execute(
            perm.insert().values(
                code="administrator_account.manage", name="管理员账号管理", **stamp
            )
        )
    db.execute(
        t["audit_log"]
        .insert()
        .values(
            action="migration.enrollment.current_baseline",
            resource_type="EnrollmentMigration",
            resource_id="f26a1014e001",
            after_json={**counts, "past_history": "UNKNOWN", "administrator_grants": "NONE"},
            created_at=now,
        )
    )
